function verifyNativeOriginals(n,smoke,parity,crypto,pkg,expected){
  const errors=[],sum=o=>Object.values(o).reduce((a,b)=>a+b,0),eq=(a,b,label)=>{if(a!==b)errors.push({label,actual:a,expected:b});},keysEqual=(a,b)=>JSON.stringify(Object.keys(a).sort())===JSON.stringify(Object.keys(b).sort());
  const q=n.queryCounts,ds=q.rpcActions.queryDiagnostics,scalar=["queryCalls","pgProtocolReceiveBytes","pgProtocolSendBytes","closedConnections","unknownReadings"],bucket=["queryOperations","unattributedSources"];
  const stats={records:0,checkpoints:0,segments:0,bucketCells:0,ordinalRows:0},windows={};
  eq(n.revision,expected.checkout,"lifecycle.revision");eq(smoke.revision,expected.checkout,"smoke.revision");eq(parity.appRevision,expected.checkout,"parity.appRevision");eq(parity.harnessRevision,expected.checkout,"parity.harnessRevision");eq(crypto.revision,expected.checkout,"crypto.revision");
  eq(n.result,"passed","lifecycle.result");eq(smoke.result,"passed","smoke.result");eq(parity.result,"passed","parity.result");eq(crypto.passed,true,"crypto.passed");eq(pkg.passed,true,"package.passed");
  for(const [name,w] of Object.entries(q.windows)){
    eq(w.status,"complete",name+".status");const cp=w.checkpoints,sg=w.segments;stats.checkpoints+=cp.length;stats.segments+=sg.length;
    eq(cp.length,sg.length+1,name+".checkpoint count");
    const record=(v,label)=>{stats.records++;eq(sum(v.queryOperations),v.queryCalls,label+".operation sum");eq(sum(v.unattributedSources),v.queryOperations.unattributed,label+".unattributed sum");eq(Object.keys(v.queryOperations).length,17,label+".operation bucket count");eq(Object.keys(v.unattributedSources).length,78,label+".source bucket count");stats.bucketCells+=Object.keys(v.queryOperations).length+Object.keys(v.unattributedSources).length;};
    for(let i=0;i<cp.length;i++)record(cp[i].snapshot,name+".cp"+i);
    const delta=(v,a,b,label)=>{for(const k of scalar)eq(v[k],b[k]-a[k],label+"."+k);for(const key of bucket){if(!keysEqual(v[key],a[key])||!keysEqual(v[key],b[key]))errors.push({label:label+"."+key+" keys"});for(const k of Object.keys(v[key]))eq(v[key][k],b[key][k]-a[key][k],label+"."+key+"."+k);}eq(v.startedAt,new Date(a.endedAt).toISOString(),label+".startedAt");eq(v.finishedAt,new Date(b.endedAt).toISOString(),label+".finishedAt");eq(v.durationMs,b.endedAt-a.endedAt,label+".durationMs");};
    for(let i=0;i<sg.length;i++){record(sg[i],name+".segment"+i);delta(sg[i],cp[i].snapshot,cp[i+1].snapshot,name+".segment"+i);}
    record(w.total,name+".total");delta(w.total,cp[0].snapshot,cp.at(-1).snapshot,name+".total");
    for(const k of scalar)eq(w.total[k],sg.reduce((s,g)=>s+g[k],0),name+".segments."+k);
    for(const b of bucket)for(const k of Object.keys(w.total[b]))eq(w.total[b][k],sg.reduce((s,g)=>s+g[b][k],0),name+".segments."+b+"."+k);
    const d=ds.windows[name];eq(d.fromQueryCalls,cp[0].snapshot.queryCalls,name+".diagnostic start");eq(d.toQueryCalls,cp.at(-1).snapshot.queryCalls,name+".diagnostic end");eq(d.expectedQueries,w.total.queryCalls,name+".diagnostic expected");eq(d.queries.length,d.capturedQueries,name+".diagnostic captured");eq(d.uncapturedQueries,d.expectedQueries-d.queries.length,name+".uncaptured count");
    const projection=(rows,v,label)=>{const ops=Object.fromEntries(Object.keys(v.queryOperations).map(k=>[k,0])),sources=Object.fromEntries(Object.keys(v.unattributedSources).map(k=>[k,0]));for(const row of rows){const key=ds.scopeKeys[row[3]];if(key in sources){sources[key]++;ops.unattributed++;}else if(key in ops)ops[key]++;else errors.push({label:label+".unknownScope",index:row[3]});}for(const k of Object.keys(ops))eq(ops[k],v.queryOperations[k],label+".ops."+k);for(const k of Object.keys(sources))eq(sources[k],v.unattributedSources[k],label+".sources."+k);};
    let uc=0,us=0;for(let i=0;i<d.queries.length;i++){const row=d.queries[i];eq(row.length,4,name+".ordinal columns");eq(row[0],d.fromQueryCalls+i+1,name+".ordinal contiguous "+i);if(!ds.contexts[row[1]])errors.push({label:name+".context index",index:row[1]});if(!ds.statements[row[2]])errors.push({label:name+".statement index",index:row[2]});if(ds.contexts[row[1]]?.status==="unknown")uc++;if(ds.statements[row[2]]?.status==="unknown")us++;}
    stats.ordinalRows+=d.queries.length;eq(uc,d.unknownContextQueries,name+".unknown contexts");eq(us,d.unknownStatementQueries,name+".unknown statements");projection(d.queries,w.total,name+".ordinal total");
    eq(d.segments.length,sg.length,name+".diagnostic segments");
    for(let i=0;i<sg.length;i++){eq(d.segments[i].phase,sg[i].phase,name+".diagnostic segment phase");eq(d.segments[i].fromQueryCalls,cp[i].snapshot.queryCalls,name+".diagnostic segment from");eq(d.segments[i].toQueryCalls,cp[i+1].snapshot.queryCalls,name+".diagnostic segment to");projection(d.queries.filter(r=>r[0]>d.segments[i].fromQueryCalls&&r[0]<=d.segments[i].toQueryCalls),sg[i],name+".ordinal segment"+i);}
    const rpc={};for(const [kind,collection]of [["physical",q.rpcActions.windows],["logical",q.rpcActions.logical.windows]]){const r=collection[name],fields=["startedInWindow","completedInWindow","crossesStart","crossesEnd","completionNotObserved","completionWithoutStart"];rpc[kind]=Object.fromEntries(fields.map(k=>[k,r.actions.reduce((s,a)=>s+a[k],0)]));eq(r.startedAt,w.total.startedAt,name+"."+kind+".start");eq(r.finishedAt,w.total.finishedAt,name+"."+kind+".end");}
    windows[name]={status:w.status,phase:w.phase,pair:w.pair??null,checkpoints:cp.length,segments:sg.map(x=>({phase:x.phase,queryCalls:x.queryCalls,receiveBytes:x.pgProtocolReceiveBytes,sendBytes:x.pgProtocolSendBytes})),total:{queryCalls:w.total.queryCalls,receiveBytes:w.total.pgProtocolReceiveBytes,sendBytes:w.total.pgProtocolSendBytes,unknownReadings:w.total.unknownReadings},diagnostics:{status:d.status,ordinalRows:d.queries.length,uncaptured:d.uncapturedQueries,unknownContext:uc,unknownStatement:us,reasons:d.reasons},rpc};
  }
  if(windows.nativeLogin.total.queryCalls>windows.webLogin.total.queryCalls)errors.push({label:"native full-window exceeds web"});
  if(windows["startup-bundled"].total.queryCalls>windows["startup-hosted"].total.queryCalls)errors.push({label:"native first startup exceeds hosted"});
  eq(windows["startup-bundled"].pair,1,"bundled FIRST");eq(windows["startup-hosted"].pair,1,"hosted FIRST");eq(ds.capture.overflow,false,"diagnostic overflow");eq(ds.capture.droppedQueries,0,"diagnostic dropped");
  eq(n.coldStart.pairs,5,"unchanged cold pair count");for(const c of n.checks)eq(c.result,"passed","lifecycle check "+c.name);for(const c of smoke.checks)eq(c.result,"passed","smoke check "+c.name);
  eq(parity.screens.length,parity.requiredScreens.length*parity.themes.length,"parity completeness");eq(parity.maximumChangedRatio,0.001,"parity threshold");eq(parity.colorThreshold,0,"parity color threshold");
  const seen=new Set();let changed=0,compared=0,max=0,masked=0;
  for(const s of parity.screens){const id=s.name+"|"+s.theme;if(seen.has(id))errors.push({label:"duplicate parity "+id});seen.add(id);eq(s.passed,true,"parity passed "+id);eq(s.maximumRatio,parity.maximumChangedRatio,"parity threshold "+id);eq(s.maskGeometryMatches,true,"parity mask geometry "+id);if(!parity.requiredScreens.includes(s.name)||!parity.themes.includes(s.theme))errors.push({label:"unexpected parity "+id});if(s.changedRatio>parity.maximumChangedRatio)errors.push({label:"parity over threshold "+id});if(Math.abs(s.changedRatio-s.changedPixels/s.comparedPixels)>1e-12)errors.push({label:"parity pixel ratio "+id});changed+=s.changedPixels;compared+=s.comparedPixels;max=Math.max(max,s.changedRatio);if(s.masks.length)masked++;}
  eq(parity.pageErrors.length,0,"parity page errors");eq(crypto.launches.length,3,"crypto launches");eq(crypto.distinctProcesses,3,"crypto distinct processes");eq(crypto.sameImmutablePackage,true,"crypto immutable package");
  for(const [i,l]of crypto.launches.entries()){eq(l.passed,true,"crypto passed"+i);eq(l.processExited,true,"crypto process exited"+i);eq(l.keychainLog.lookupFailureCount,0,"crypto keychain failures"+i);eq(l.keychainLog.truncated,false,"crypto log truncation"+i);}
  return {schemaVersion:1,head:expected.head,tree:expected.tree,actualCheckout:expected.checkout,arithmetic:{...stats,errors},windows,scope:q.scope,exclusions:q.exclusions,background:q.background,boundary:q.boundary,login:q.login,startup:q.startup,cold:n.coldStart,parity:{screens:parity.screens.length,required:parity.requiredScreens.length,themes:parity.themes,maximumChangedRatio:parity.maximumChangedRatio,colorThreshold:parity.colorThreshold,totalComparedPixels:compared,changedPixels:changed,maxObserved:max,maskedScreens:masked,masks:parity.masksAllowed,excludedDesktopOnly:parity.excludedDesktopOnly,pageErrors:parity.pageErrors},crypto,smoke,cleanup:{lifecycle:n.cleanupStages,lifecycleNative:n.nativeCleanup,lifecycleWorkspace:n.workspaceNameCleanup,lifecycleObservation:n.accountObservation,parity:parity.cleanup,parityNative:parity.nativeCleanup,parityWorkspace:parity.workspaceNameCleanup},nativeSetup:n.nativeSetup,limitations:{diagnosticsIncomplete:Object.values(windows).some(x=>x.diagnostics.status!=="complete"),unknownFineAttributionPreserved:true,installedDaemonSeparateFromCandidate:true,rootViewedParityPngPixels:false,productionAcceptance:false,apiProcessProtocolBytesAreNotWholeNetworkBytes:true}};
}
